#!/usr/bin/env node
// Converts the MIT-licensed MuscleMap Swift path files into the iOS app's own geometry file.
//
// Same upstream, same vendored source files and same slug rules as `gen-body-geometry.mjs`
// (which emits the web app's `bodyGeometry.gen.ts`), so the phone and the web draw the *same*
// body — one upstream, two generated files, neither hand-edited.
//
// Source: https://github.com/melihcolpan/MuscleMap (MIT) — see NOTICE.md at the repo root.
// openGym's own converted paths are AGPL and must never be copied.
import { readFileSync, writeFileSync } from 'node:fs';

const OUT = 'ios/BoopKit/Sources/BoopDesign/Napkelte/BodyGeometry.gen.swift';
const FRONT = 'scripts/vendor/musclemap/MaleFrontPaths.swift';
const BACK = 'scripts/vendor/musclemap/MaleBackPaths.swift';

/** `BodyPartPathData(slug: .upperChest, left: [...], right: [...])` → { 'upper-chest': [path, …] }. */
function parse(swift) {
  const shapes = {};
  for (const block of swift.split('BodyPartPathData(').slice(1)) {
    const slug = block.match(/slug:\s*\.([A-Za-z]+)/)?.[1];
    if (!slug) continue;
    const kebab = slug.replace(/([a-z])([A-Z])/g, '$1-$2').toLowerCase();
    const paths = [...block.matchAll(/"((?:[^"\\]|\\.)*)"/g)].map((m) => m[1]).filter((p) => /^[Mm]/.test(p));
    if (paths.length) shapes[kebab] = (shapes[kebab] ?? []).concat(paths);
  }
  return shapes;
}

function swiftDict(shapes) {
  return Object.entries(shapes)
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([slug, paths]) => {
      const list = paths.map((p) => `                "${p}",`).join('\n');
      return `            "${slug}": [\n${list}\n            ],`;
    })
    .join('\n');
}

const front = parse(readFileSync(FRONT, 'utf8'));
const back = parse(readFileSync(BACK, 'utf8'));

const out = `// Generated by scripts/gen-body-geometry-swift.mjs — do not hand-edit.
//
// Body geometry from MuscleMap (https://github.com/melihcolpan/MuscleMap), MIT License,
// Copyright (c) Melih Colpan. See NOTICE.md at the repository root.
//
// The same upstream and the same generator rules as the web app's \`bodyGeometry.gen.ts\`, so
// both draw the same body. Each value is one or more SVG path strings in the view box below;
// \`NKPath\` turns them into a SwiftUI \`Path\`.

public enum NKBodyView: String, Sendable, CaseIterable {
    case front, back
}

public enum NKBodyGeometry {
    /// Every drawable shape of a view, by its slug. The box they are drawn in is **measured**
    /// from them (\`NKBodyPaths.viewBox\`) rather than written down here: upstream draws the two
    /// bodies side by side in one canvas, so the back body's own frame does not start at the
    /// origin, and a hand-copied box silently clips it.
    public static func shapes(_ view: NKBodyView) -> [String: [String]] {
        switch view {
        case .front: front
        case .back: back
        }
    }

    static let front: [String: [String]] = [
${swiftDict(front)}
    ]

    static let back: [String: [String]] = [
${swiftDict(back)}
    ]
}
`;

writeFileSync(OUT, out);
const count = (s) => Object.keys(s).length;
console.log(`✅ wrote ${OUT} — ${count(front)} front shapes, ${count(back)} back shapes`);
